"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["3732"],{63294(e){e.exports=JSON.parse('{"id":"FIN-1223","slug":"velocity-of-money","term":"Velocity of Money","also_known_as":[],"difficulty":"Advanced","definition":"The velocity of money is the average number of times each unit of money is spent on goods and services during a period, calculated as nominal GDP divided by the money supply.","explanation":["Velocity measures how actively money circulates in an economy. If people and businesses spend money quickly, velocity is high. If they hold on to it, velocity is low.","For example, if nominal GDP is 2,000 and the money supply is 500, the velocity of money is 4. On average, each unit of money is used four times a year to buy final goods and services.","Velocity is part of the quantity theory of money, which states that money supply multiplied by velocity equals nominal GDP. If velocity were stable, growth in the money supply would translate directly into growth in nominal spending, and possibly inflation.","In practice, velocity changes considerably. It tends to fall during recessions and periods of uncertainty, when people save more, and when interest rates are very low, since holding money costs little. Velocity in many economies fell sharply after 2008 and again in 2020. This instability is one reason most central banks no longer target the money supply directly."],"note":"","total":1500,"prev":{"slug":"vega","term":"Vega"},"next":{"slug":"venture-capital","term":"Venture Capital"}}')}}]);